(7475561, 1187879, 10848, '<td valign="top">Yep, I gave you a ten on this one. Why? This image is perfectly composed, has an emotional aspect that I find both charming and expressive. Congrats on an excellent image and I hope you do well.</td>', 'Yep, I gave you a ten on this one. Why? This image is perfectly composed, has an emotional aspect that I find both charming and expressive. Congrats on an excellent image and I hope you do well.', '2016-09-24 20:55:05.000000', NULL, 1),
(7475562, 1187942, 10848, '<td valign="top">A ten for you on this one from me. How often do you have a photo challenge about hats and wonder upon a gentleman with a hat on and a pigeon perched delicately on the hat. Great composition, wonderful expression, great light and over-all wonderful image. I hope this one hits the front page. Good luck!</td>', 'A ten for you on this one from me. How often do you have a photo challenge about hats and wonder upon a gentleman with a hat on and a pigeon perched delicately on the hat. Great composition, wonderful expression, great light and over-all wonderful image. I hope this one hits the front page. Good luck!', '2016-09-24 20:56:54.000000', NULL, 1),
(7475563, 1187885, 10848, '<td valign="top">I gave this a high score because I love the way you isolated  your subject to where the eye goes straight to the "Man in the hat", also I love the facial expression of the lady in front of him, that is hilarious.</td>', 'I gave this a high score because I love the way you isolated  your subject to where the eye goes straight to the "Man in the hat", also I love the facial expression of the lady in front of him, that is hilarious.', '2016-09-24 20:58:06.000000', NULL, 1),
(7475564, 1187917, 10848, '<td valign="top">This is another high score for me. What a find!!! Love the facial expression and the body language of the man, really very humorous that the statue and the man appear to be viewing the same thing with different reactions. Good luck!</td>', 'This is another high score for me. What a find!!! Love the facial expression and the body language of the man, really very humorous that the statue and the man appear to be viewing the same thing with different reactions. Good luck!', '2016-09-24 20:59:49.000000', NULL, 1),
(7475565, 1188007, 10848, '<td valign="top">WOW, this is amazing! Love it, such a outstanding find indeed. Well executed, I like the black and white effect, really adds impact to the over-all image. Bumping this one up. Good luck!</td>', 'WOW, this is amazing! Love it, such a outstanding find indeed. Well executed, I like the black and white effect, really adds impact to the over-all image. Bumping this one up. Good luck!', '2016-09-24 21:01:01.000000', NULL, 1),
