(7476394, 1187786, 172697, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by flaherma:</b></div><hr/><i> That''s a great story, glad you got the shot. He is well worth sharing! Congrats on the ribbon :) </i></td></tr></table> <br/> <br/>Thank you so much Mary Ann, I''m glad you liked both the shot and the story behind it!</td>', 'Originally posted by flaherma: That''s a great story, glad you got the shot. He is well worth sharing! Congrats on the ribbon :)   Thank you so much Mary Ann, I''m glad you liked both the shot and the story behind it!', '2016-09-30 10:53:48.000000', NULL, 0),
(7476395, 1187911, 140305, '<td valign="top">Just have to say how much I''m enjoying your work lately Niall. This one in particular really resonated with me, not sure why but I can''t stop looking! Wonderful photo :)</td>', 'Just have to say how much I''m enjoying your work lately Niall. This one in particular really resonated with me, not sure why but I can''t stop looking! Wonderful photo :)', '2016-09-30 10:56:04.000000', NULL, 0),
